import { el, button, field, modal, busy, notify } from './utils.js';
import { api } from './service.js';
import { accountName } from './model.js';
export function renderMailbox(data) {
  const accounts = data.accounts.filter((account) => ['gmail', 'outlook', 'zoho'].includes(account.provider)); const body = el('div'); const picker = el('select', { class: 'field-control', 'aria-label': 'Mailbox account' }, el('option', { value: '', text: 'Choose a mailbox…' }), ...accounts.map((account) => el('option', { value: account.id, text: `${accountName(account)} · ${account.provider}` }))); let selected;
  const root = el('section', { class: 'content-panel' }, el('div', { class: 'panel-toolbar' }, el('h2', { text: 'Mailbox drafts' }), picker), el('p', { class: 'inline-note', text: 'Create and edit drafts in Gmail, Outlook or Zoho. Saving a draft does not send it. Zoho sending remains manual.' }), body);
  async function load() {
    selected = accounts.find((account) => account.id === picker.value); if (!selected) { body.replaceChildren(el('p', { class: 'inline-note', text: accounts.length ? 'Select a connected mailbox to load its drafts.' : 'Connect a mailbox through the administrator OAuth setup first, then refresh. No passwords or tokens belong in this form.' })); return; }
    body.replaceChildren(el('div', { class: 'loading-state', text: 'Loading mailbox drafts…' }));
    try { const value = await api('drafts-list', { accountId: selected.id }); const list = el('div'); const create = button('Create mailbox draft', () => edit(), 'small'); create.disabled = !data.roles.some((role) => ['admin', 'operator'].includes(role)); list.append(el('div', { class: 'panel-toolbar' }, el('span', { class: 'muted', text: `${value.drafts.length} drafts` }), create)); for (const draft of value.drafts) list.append(el('article', { class: 'queue-card' }, el('span', { class: 'badge', text: 'Draft' }), el('div', {}, el('h3', { text: draft.subject || '(No subject)' }), el('p', { text: draft.snippet || '' })), button('Edit draft', async () => { try { const detail = await api('drafts-get', { accountId: selected.id, draftId: draft.id }); edit(detail); } catch (error) { notify(error.message); } }, 'small'))); body.replaceChildren(list); } catch (error) { body.replaceChildren(el('div', { class: 'banner error', text: error.message })); }
  }
  function edit(draft) {
    const account = selected; const content = draft?.content || {}; const m = modal(draft ? 'Edit mailbox draft' : 'Create mailbox draft', 'This saves a provider draft. It does not enqueue or send an email.');
    const to = el('input', { class: 'field-control', name: 'to', autocomplete: 'off' }); to.value = (content.to || []).map((v) => v.address).join(', '); const subject = el('input', { class: 'field-control', name: 'subject', maxlength: 1000, autocomplete: 'off' }); subject.value = content.subject || '';
    const text = el('textarea', { class: 'field-control', name: 'text', rows: 9 }); text.value = content.text || ''; m.content.append(el('div', { class: 'review-content' }, field('To (comma-separated email addresses)', to), field('Subject', subject), field('Message', text), el('p', { class: 'flow-note', text: account.provider === 'zoho' ? 'Open Zoho to send this draft after saving.' : 'Threading and existing supported metadata are retained by the mailbox adapter.' })));
    const save = button('Save mailbox draft', () => busy(save, async () => { const input = { ...content, ...(draft?.id ? { id: draft.id } : {}), from: content.from || { address: account.sender.address, name: account.sender.name }, to: to.value.split(',').map((address) => ({ address: address.trim() })).filter((value) => value.address), subject: subject.value, text: text.value, headers: content.headers || {} }; await api('drafts-save', { accountId: account.id, input }); m.close(); await load(); notify('Mailbox draft saved. Nothing was sent.'); }), 'primary'); save.disabled = !data.roles.some((role) => ['admin', 'operator'].includes(role)); m.bottom.append(button('Close', m.close), save);
    if (account.provider === 'zoho') m.bottom.append(el('a', { class: 'button', href: 'https://mail.zoho.com/', target: '_blank', rel: 'noopener noreferrer', text: 'Open in Zoho' }));
    if (draft && !save.disabled) { const remove = button('Delete draft', () => { const confirm = button('Delete this mailbox draft', () => busy(confirm, async () => { await api('drafts-delete', { accountId: account.id, draftId: draft.id }); m.close(); await load(); notify('Mailbox draft deleted.'); }), 'danger'); m.bottom.replaceChildren(button('Keep draft', m.close), confirm); }, 'danger'); m.bottom.append(remove); }
  }
  picker.addEventListener('change', () => { void load(); }); void load(); return root;
}
